f;?><p class="muted"><?=e($p['description'])?></p><div class="chips"><span class="chip"><?=e($p['study_track'])?></span><span class="chip"><?=e($p['code'])?></span></div><a class="btn" href="?page=programs&detail=<?=$p['id']?>">View Details</a></div><?php endforeach;?></div><?php }}
